const mongoose = require('mongoose');

/**
 * In-app notification. One row per recipient per event. Auto-generated by the
 * lifecycle (proposal accepted, deposit funded, work delivered, revision
 * requested, payment released, gig ordered, new message, etc).
 */
const notificationSchema = new mongoose.Schema({
  // Who receives it.
  userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, index: true },

  // Machine type for icon/grouping; see notification.service.TYPES.
  type: { type: String, required: true },

  title: { type: String, required: true },
  message: { type: String, default: '' },

  // Where clicking it should take the user (frontend route).
  link: { type: String, default: '' },

  // Optional references for context.
  jobId: { type: mongoose.Schema.Types.ObjectId, ref: 'Job' },
  gigId: { type: mongoose.Schema.Types.ObjectId, ref: 'Gig' },
  proposalId: { type: mongoose.Schema.Types.ObjectId, ref: 'Proposal' },

  read: { type: Boolean, default: false, index: true },
  readAt: Date,
}, { timestamps: true });

// Most queries are "my unread, newest first".
notificationSchema.index({ userId: 1, createdAt: -1 });

module.exports = mongoose.model('Notification', notificationSchema);
